                if startcolor:
                    out.append(ch)
                    if key: out.append(M)
                    elif val: out.append(C)
                    ssc = True
                    key = False; val = False; startcolor = False
                else:
                    out.append(E); out.append(ch)
                    endcolor = True
                    ssc = False
        elif ch == ',':
            if not ssc:
                startcolor = True; key = True; val = False
                if not endcolor:
                    out.append(E); endcolor = True
            out.append(ch)
        elif ch == ':':
            if not ssc:
                key = False; val = True; startcolor = True
                if not endcolor:
                    out.append(E); endcolor = True
            out.append(ch)
