// Package httplib is a small HTTP request builder used by bat.
package httplib

import (
	"bytes"
	"compress/gzip"
	"crypto/tls"
	"encoding/json"
	"io"
	"log"
	"net"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"sync"
	"time"
)

// Settings holds the options used when sending a request.
type Settings struct {
	ShowDebug        bool
	UserAgent        string
	ConnectTimeout   time.Duration
	ReadWriteTimeout time.Duration
	TLSClientConfig  *tls.Config
	Proxy            func(*http.Request) (*url.URL, error)
	Transport        http.RoundTripper
	Gzip             bool
	DumpBody         bool
}

var defaultSettings = Settings{
	UserAgent:        "bat",
	ConnectTimeout:   60 * time.Second,
	ReadWriteTimeout: 60 * time.Second,
	Gzip:             true,
	DumpBody:         true,
}

var settingsMu sync.Mutex

// SetDefaultSettings overrides the settings used by new requests.
func SetDefaultSettings(s Settings) {
	settingsMu.Lock()
	defer settingsMu.Unlock()
	defaultSettings = s
	if defaultSettings.ConnectTimeout == 0 {
		defaultSettings.ConnectTimeout = 60 * time.Second
	}
	if defaultSettings.ReadWriteTimeout == 0 {
		defaultSettings.ReadWriteTimeout = 60 * time.Second
	}
}

// Request wraps an *http.Request together with parameters to send.
type Request struct {
	mu       sync.Mutex
	url      string
	req      *http.Request
	params   map[string]string
	settings Settings
	resp     *http.Response
	body     []byte
	dump     []byte
}

// NewRequest creates a request for the given url and method.
func NewRequest(rawurl, method string) *Request {
	u, err := url.Parse(rawurl)
	if err != nil {
		log.Fatal(err)
	}
	req := &http.Request{
		URL:        u,
		Method:     method,
		Header:     make(http.Header),
		Proto:      "HTTP/1.1",
		ProtoMajor: 1,
		ProtoMinor: 1,
	}
	settingsMu.Lock()
	s := defaultSettings
	settingsMu.Unlock()
	return &Request{
		url:      rawurl,
		req:      req,
		params:   map[string]string{},
		settings: s,
		resp:     &http.Response{},
	}
}

// Debug enables dumping of the outgoing request.
func (b *Request) Debug(on bool) *Request {
	b.settings.ShowDebug = on
	return b
}

// SetUserAgent sets the default User-Agent header value.
func (b *Request) SetUserAgent(ua string) *Request {
	b.settings.UserAgent = ua
	return b
}

// SetBasicAuth sets HTTP basic authentication credentials.
func (b *Request) SetBasicAuth(user, pass string) *Request {
	b.req.SetBasicAuth(user, pass)
	return b
}

// SetTLSClientConfig sets the TLS configuration of the transport.
func (b *Request) SetTLSClientConfig(c *tls.Config) *Request {
	b.settings.TLSClientConfig = c
	return b
}

// SetProxy sets the proxy function of the transport.
func (b *Request) SetProxy(p func(*http.Request) (*url.URL, error)) *Request {
	b.settings.Proxy = p
	return b
}

// Header sets a request header.
func (b *Request) Header(key, value string) *Request {
	b.req.Header.Set(key, value)
	return b
}

// SetHost overrides the Host of the request.
func (b *Request) SetHost(host string) *Request {
	b.req.Host = host
	return b
}

// Param adds a query / form parameter.
func (b *Request) Param(key, value string) *Request {
	b.params[key] = value
	return b
}

// Body sets a raw request body.
func (b *Request) Body(data interface{}) *Request {
	switch t := data.(type) {
	case string:
		b.req.Body = io.NopCloser(bytes.NewBufferString(t))
		b.req.ContentLength = int64(len(t))
	case []byte:
		b.req.Body = io.NopCloser(bytes.NewBuffer(t))
		b.req.ContentLength = int64(len(t))
	}
	return b
}

// JSONBody encodes obj as JSON and uses it as the request body.
func (b *Request) JSONBody(obj interface{}) (*Request, error) {
	if b.req.Body == nil && obj != nil {
		buf := bytes.NewBuffer(nil)
		enc := json.NewEncoder(buf)
		if err := enc.Encode(obj); err != nil {
			return b, err
		}
		b.req.Body = io.NopCloser(buf)
		b.req.ContentLength = int64(buf.Len())
		b.req.Header.Set("Content-Type", "application/json")
	}
	return b, nil
}

// GetRequest returns the underlying *http.Request.
func (b *Request) GetRequest() *http.Request {
	return b.req
}

// DumpRequest returns the dump of the last sent request.
func (b *Request) DumpRequest() []byte {
	return b.dump
}

func (b *Request) buildURL(paramBody string) {
	if b.req.Method == "GET" && len(paramBody) > 0 {
		if strings.Contains(b.url, "?") {
			b.url += "&" + paramBody
		} else {
			b.url = b.url + "?" + paramBody
		}
		return
	}
	if (b.req.Method == "POST" || b.req.Method == "PUT" || b.req.Method == "PATCH") && b.req.Body == nil {
		if len(paramBody) > 0 {
			b.Header("Content-Type", "application/x-www-form-urlencoded")
			b.Body(paramBody)
		}
	}
}

// Response sends the request (once) and returns the response.
func (b *Request) Response() (*http.Response, error) {
	if b.resp.StatusCode != 0 {
		return b.resp, nil
	}
	resp, err := b.SendOut()
	if err != nil {
		return nil, err
	}
	b.resp = resp
	return resp, nil
}

// SendOut builds and sends the request.
func (b *Request) SendOut() (*http.Response, error) {
	b.mu.Lock()
	var paramBody string
	if len(b.params) > 0 {
		var buf bytes.Buffer
		for k, v := range b.params {
			buf.WriteString(url.QueryEscape(k))
			buf.WriteByte('=')
			buf.WriteString(url.QueryEscape(v))
			buf.WriteByte('&')
		}
		paramBody = buf.String()
		paramBody = paramBody[0 : len(paramBody)-1]
	}

	b.buildURL(paramBody)
	u, err := url.Parse(b.url)
	if err != nil {
		b.mu.Unlock()
		return nil, err
	}
	b.req.URL = u

	trans := b.settings.Transport
	if trans == nil {
		trans = &http.Transport{
			TLSClientConfig: b.settings.TLSClientConfig,
			Proxy:           b.settings.Proxy,
			Dial:            TimeoutDialer(b.settings.ConnectTimeout, b.settings.ReadWriteTimeout),
		}
	}
	client := &http.Client{Transport: trans}

	if b.settings.UserAgent != "" && b.req.Header.Get("User-Agent") == "" {
		b.req.Header.Set("User-Agent", b.settings.UserAgent)
	}

	if b.settings.ShowDebug {
		dump, err := httputil.DumpRequest(b.req, b.settings.DumpBody)
		if err != nil {
			println(err.Error())
		}
		b.dump = dump
	}
	req := b.req
	b.mu.Unlock()
	return client.Do(req)
}

// Bytes returns the (decompressed) response body.
func (b *Request) Bytes() ([]byte, error) {
	if b.body != nil {
		return b.body, nil
	}
	resp, err := b.Response()
	if err != nil {
		return nil, err
	}
	if resp.Body == nil {
		return nil, nil
	}
	defer resp.Body.Close()
	if b.settings.Gzip && resp.Header.Get("Content-Encoding") == "gzip" {
		reader, err := gzip.NewReader(resp.Body)
		if err != nil {
			return nil, err
		}
		b.body, err = io.ReadAll(reader)
		if err != nil {
			return nil, err
		}
	} else {
		b.body, err = io.ReadAll(resp.Body)
		if err != nil {
			return nil, err
		}
	}
	return b.body, nil
}

// TimeoutDialer returns a dial function with connect and read/write timeouts.
func TimeoutDialer(cTimeout time.Duration, rwTimeout time.Duration) func(netw, addr string) (net.Conn, error) {
	return func(netw, addr string) (net.Conn, error) {
		conn, err := net.DialTimeout(netw, addr, cTimeout)
		if err != nil {
			return nil, err
		}
		conn.SetDeadline(time.Now().Add(rwTimeout))
		return conn, nil
	}
}
