// getHTTP builds the request from the method, the url and the request items.
//
// Items are interpreted in this order:
//
//	key:value   request header
//	key=value   query string (GET / form) or JSON field
//	key=@file   same as above, the value is read from file
func getHTTP(method string, url string, args []string) (r *httplib.Request) {
	r = httplib.NewRequest(url, method)
	r.Header("Accept-Encoding", "gzip, deflate")
	if *isjson {
		r.Header("Accept", "application/json")
	} else if form || method == "GET" {
		r.Header("Accept", "*/*")
	} else {
		r.Header("Accept", "application/json")
	}
	for i := range args {
		// Headers
		strs := strings.Split(args[i], ":")
		if len(strs) >= 2 {
			if strs[0] == "Host" {
				r.SetHost(strings.Join(strs[1:], ":"))
			}
			r.Header(strs[0], strings.Join(strs[1:], ":"))
			continue
		}
		// Params
		strs = strings.Split(args[i], "=")
		if len(strs) >= 2 {
			value := strings.Join(strs[1:], "=")
			if strings.HasPrefix(value, "@") {
				value = readItemFile(strings.TrimLeft(value, "@"))
			}
			if form || method == "GET" {
				r.Param(strs[0], value)
			} else {
				jsonmap[strs[0]] = value
			}
			continue
		}
	}
	if !form && len(jsonmap) > 0 {
		r.JSONBody(jsonmap)
	}
	return
