package main

import (
	"fmt"
	"math"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

const (
	// DefaultRefreshRate is the delay between two redraws of the bar.
	DefaultRefreshRate = time.Millisecond * 200
	// DefaultBarWidth is the width of the whole progress line.
	DefaultBarWidth = 123
)

// ProgressBar is a minimal text progress bar used while downloading.
type ProgressBar struct {
	current int64 // accessed atomically

	Total                        int64
	RefreshRate                  time.Duration
	ShowPercent, ShowCounters    bool
	ShowSpeed, ShowTimeLeft      bool
	ShowBar, ShowFinalTime       bool
	Width                        int
	BarStart, BarEnd             string
	Empty, Current, CurrentN     string

	mu           sync.Mutex
	isFinish     bool
	startTime    time.Time
	currentValue int64
}

// NewProgressBar creates a progress bar for total bytes.
func NewProgressBar(total int64) *ProgressBar {
	return &ProgressBar{
		Total:         total,
		RefreshRate:   DefaultRefreshRate,
		ShowPercent:   true,
		ShowCounters:  true,
		ShowSpeed:     true,
		ShowTimeLeft:  true,
		ShowBar:       true,
		ShowFinalTime: true,
		Width:         DefaultBarWidth,
		BarStart:      "[",
		BarEnd:        "]",
		Empty:         "_",
		Current:       "=",
		CurrentN:      ">",
	}
}

// Start starts drawing the bar in the background.
func (pb *ProgressBar) Start() {
	pb.startTime = time.Now()
	if pb.Total == 0 {
		pb.ShowBar = false
		pb.ShowTimeLeft = false
		pb.ShowPercent = false
	}
	go pb.writer()
}

// Write implements io.Writer, counting the written bytes.
func (pb *ProgressBar) Write(p []byte) (int, error) {
	n := len(p)
	atomic.AddInt64(&pb.current, int64(n))
	return n, nil
}

// Update redraws the bar when the progress changed.
func (pb *ProgressBar) Update() {
	pb.mu.Lock()
	defer pb.mu.Unlock()
	if pb.isFinish {
		return
	}
	c := atomic.LoadInt64(&pb.current)
	if c != pb.currentValue {
		pb.write(c)
		pb.currentValue = c
	}
}

func (pb *ProgressBar) finished() bool {
	pb.mu.Lock()
	defer pb.mu.Unlock()
	return pb.isFinish
}

func (pb *ProgressBar) writer() {
	for {
		if pb.finished() {
			break
		}
		pb.Update()
		time.Sleep(pb.RefreshRate)
	}
}

// Finish draws the bar a last time, showing the elapsed time.
func (pb *ProgressBar) Finish() {
	pb.mu.Lock()
	defer pb.mu.Unlock()
	pb.isFinish = true
	pb.write(atomic.LoadInt64(&pb.current))
}

func (pb *ProgressBar) write(current int64) {
	width := pb.Width
	var percentBox, countersBox, timeLeftBox, speedBox, barBox, end, out string

	// percents
	if pb.ShowPercent {
		percent := float64(current) / (float64(pb.Total) / float64(100))
		percentBox = fmt.Sprintf(" %#.02f %% ", percent)
	}

	// counters
	if pb.ShowCounters {
		if pb.Total > 0 {
			countersBox = fmt.Sprintf("%s / %s ", FormatBytes(current), FormatBytes(pb.Total))
		} else {
			countersBox = FormatBytes(current) + " "
		}
	}

	// time left
	fromStart := time.Now().Sub(pb.startTime)
	if pb.isFinish {
		if pb.ShowFinalTime {
			left := (fromStart / time.Second) * time.Second
			timeLeftBox = left.String()
		}
	} else if pb.ShowTimeLeft && current > 0 {
		perEntry := fromStart / time.Duration(current)
		left := time.Duration(pb.Total-current) * perEntry
		left = (left / time.Second) * time.Second
		timeLeftBox = left.String()
	}

	// speed
	if pb.ShowSpeed && current > 0 {
		fromStart := time.Now().Sub(pb.startTime)
		speed := float64(current) / (float64(fromStart) / float64(time.Second))
		speedBox = FormatBytes(int64(speed)) + "/s "
	}

	// bar
	if pb.ShowBar {
		size := width - len(countersBox+pb.BarStart+pb.BarEnd+percentBox+timeLeftBox+speedBox)
		if size > 0 {
			curCount := int(math.Ceil((float64(current) / float64(pb.Total)) * float64(size)))
			emptCount := size - curCount
			barBox = pb.BarStart
			if emptCount < 0 {
				emptCount = 0
			}
			if curCount > size {
				curCount = size
			}
			if emptCount <= 0 {
				barBox += strings.Repeat(pb.Current, curCount)
			} else if curCount > 0 {
				barBox += strings.Repeat(pb.Current, curCount-1) + pb.CurrentN
			}
			barBox += strings.Repeat(pb.Empty, emptCount) + pb.BarEnd
		}
	}

	// check len
	out = countersBox + barBox + percentBox + speedBox + timeLeftBox
	if len(out) < width {
		end = strings.Repeat(" ", width-len(out))
	}

	fmt.Print("\r" + out + end)
}

// FormatBytes formats a number of bytes in a human readable way.
func FormatBytes(i int64) (result string) {
	switch {
	case i > (1024 * 1024 * 1024 * 1024):
		result = fmt.Sprintf("%.02f TB", float64(i)/1024/1024/1024/1024)
	case i > (1024 * 1024 * 1024):
		result = fmt.Sprintf("%.02f GB", float64(i)/1024/1024/1024)
	case i > (1024 * 1024):
		result = fmt.Sprintf("%.02f MB", float64(i)/1024/1024)
	case i > 1024:
		result = fmt.Sprintf("%.02f KB", float64(i)/1024)
	default:
		result = fmt.Sprintf("%d B", i)
	}
	result = strings.Trim(result, " ")
	return
}
