func getHTTP(method string, url string, args []string) (r *httplib.Request) {
	r = httplib.NewRequest(url, method)
	r.Header("Accept-Encoding", "gzip, deflate")
	if *isjson {
		r.Header("Accept", "application/json")
	} else if form || method == "GET" {
		r.Header("Accept", "*/*")
	} else {
		r.Header("Accept", "application/json")
	}
	for i := range args {
		item := args[i]
		// Headers
		strs := strings.Split(item, ":")
		if len(strs) >= 2 {
			if strs[0] == "Host" {
				r.SetHost(strings.Join(strs[1:], ":"))
			}
			r.Header(strs[0], strings.Join(strs[1:], ":"))
			continue
		}
		// Files, unless the data is sent as JSON
		if !*isjson {
			strs = strings.Split(item, "@")
			if len(strs) >= 2 {
				if !form {
					log.Fatal("file upload only support in forms style: -f=true")
				}
				r.PostFile(strs[0], strings.Join(strs[1:], "@"))
				continue
			}
		}
		// Params
		strs = strings.Split(item, "=")
		if len(strs) >= 2 {
			addParam(r, method, strs[0], strings.Join(strs[1:], "="))
			continue
		}
	}
	if !form && len(jsonmap) > 0 {
		r.JSONBody(jsonmap)
	}
	return
}

